#!/usr/bin/env python3
"""Offline evidence-chain quality gate for IMPERIUS CUCKED.

Checks record shape and some evidence-status inconsistencies. It CANNOT verify
that cited comic panels exist or are accurately interpreted.
"""
import argparse
import json
import re
import sys
from pathlib import Path

REQUIRED = (
    "claim_id", "position", "source_title", "issue_id", "universe",
    "source_kind", "access", "source_url", "page_panel", "observation",
    "status", "contradicts_claim", "researcher",
)
UNIVERSES = {"Earth-616", "MCU", "Alternate", "Other", "Unknown"}
SOURCES = {"primary-comic", "official-publisher", "creator-primary", "secondary", "fan", "unknown"}
ACCESS = {"panel", "official-transcript", "official-summary", "secondary-summary", "not-accessed"}
STATUS = {"DIRECTLY_ESTABLISHED", "SUPPORTED_INFERENCE", "INTERPRETIVE", "DISPUTED", "UNRESOLVED", "REFUTED"}
POSITIONS = {"SUPPORT", "COUNTER", "NEUTRAL", "CONTEXT"}
PRIMARY_ACCESS = {"panel", "official-transcript"}

FILES = [
    "README.md", "MISSION.md", "AGENTS.md", ".omp/AGENTS.md", ".omp/RULES.md",
    ".omp/config.yml", ".omp/agents/namor-investigator.md",
    ".omp/agents/franklin-investigator.md", ".omp/agents/continuity-prosecutor.md",
    ".omp/agents/independent-judge.md",
    "PROMPTS/00_DISPATCH.md", "PROMPTS/01_NAMOR.md", "PROMPTS/02_FRANKLIN.md",
    "PROMPTS/03_TIMELINE.md", "PROMPTS/04_REVIEW.md", "PROMPTS/05_FINAL.md",
    "EVIDENCE/HYPOTHESES.md", "EVIDENCE/SEED_INDEX.md", "EVIDENCE/SEEDS.csv",
    "EVIDENCE/SCHEMA.md", "OUTPUT/README.md", "scripts/start.sh",
]


def validate_record(rec: object, row: int) -> list[str]:
    prefix = f"line {row}"
    if not isinstance(rec, dict):
        return [f"{prefix}: must be a JSON object"]
    errors = []
    for field in REQUIRED:
        if field not in rec:
            errors.append(f"{prefix}: missing '{field}'")
        elif not isinstance(rec[field], str):
            errors.append(f"{prefix}: '{field}' must be a string")
    if errors:
        return errors
    for key, choices in (("universe", UNIVERSES), ("source_kind", SOURCES),
                         ("access", ACCESS), ("status", STATUS), ("position", POSITIONS)):
        if rec[key] not in choices:
            errors.append(f"{prefix}: invalid {key}: {rec[key]!r}")
    for key in ("claim_id", "source_title", "issue_id", "observation", "researcher"):
        if not rec[key].strip():
            errors.append(f"{prefix}: blank {key}")
    if rec["source_url"] and not (
        rec["source_url"].startswith("https://") or rec["source_url"].startswith("file://")
    ):
        errors.append(f"{prefix}: source_url must be HTTPS, file://, or blank")
    if rec["access"] == "panel" and rec["source_kind"] != "primary-comic":
        errors.append(f"{prefix}: panel access requires primary-comic as source_kind")
    if rec["status"] == "DIRECTLY_ESTABLISHED":
        if rec["access"] not in PRIMARY_ACCESS or not rec["page_panel"].strip() or not rec["source_url"].strip():
            errors.append(f"{prefix}: DIRECTLY_ESTABLISHED requires actual panel/transcript access, exact locator, and source_url")
    if rec["status"] == "REFUTED":
        if (rec["access"] not in PRIMARY_ACCESS or not rec["page_panel"].strip()
                or not rec["source_url"].strip() or not rec["contradicts_claim"].strip()):
            errors.append(f"{prefix}: REFUTED requires explicit contradiction text, primary panel/transcript, exact locator, and source_url")
    if rec["status"] in ("DIRECTLY_ESTABLISHED", "REFUTED") and rec["source_kind"] not in {"primary-comic", "official-publisher", "creator-primary"}:
        errors.append(f"{prefix}: {rec['status']} not supported by secondary/fan/unknown source")
    if "confidence" in rec:
        val = rec["confidence"]
        if not isinstance(val, str) or re.search(r"\d+(?:\.\d+)?\s*%", val):
            errors.append(f"{prefix}: confidence percentages require a specified calibrated method; use a qualitative rationale instead")
    return errors


def validate_ledger(path: Path) -> list[str]:
    if not path.exists():
        return [f"missing ledger file: {path}"]
    errors = []
    seen = set()
    count = 0
    for row, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        if not line.strip():
            continue
        count += 1
        try:
            rec = json.loads(line)
        except json.JSONDecodeError as exc:
            errors.append(f"line {row}: invalid JSON: {exc.msg}")
            continue
        errors.extend(validate_record(rec, row))
        if isinstance(rec, dict):
            key = (rec.get("claim_id"), rec.get("source_url"), rec.get("page_panel"), rec.get("position"))
            if key in seen:
                errors.append(f"line {row}: duplicate claim/source/panel/position; preserve source independence")
            seen.add(key)
    if count == 0:
        errors.append("ledger is empty: no research results are validated yet")
    return errors


def check_package(root: Path) -> list[str]:
    return [f"missing package file: {p}" for p in FILES if not (root / p).is_file()]


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate IMPERIUS CUCKED research packet or completed evidence ledger.")
    parser.add_argument("ledger", nargs="?", type=Path, help="Path to OUTPUT/evidence_ledger.jsonl")
    parser.add_argument("--check-package", action="store_true", help="Only check the required research packet files.")
    args = parser.parse_args()
    if args.check_package:
        errors = check_package(Path(__file__).resolve().parent.parent)
    else:
        if args.ledger is None:
            parser.error("provide a ledger path or --check-package")
        errors = validate_ledger(args.ledger)
    for error in errors:
        print("FAIL:", error, file=sys.stderr)
    if errors:
        print(f"FAIL: {len(errors)} issue(s)", file=sys.stderr)
        return 1
    print("PASS: structural evidence checks completed. Source authenticity still requires independent review.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
