#!/usr/bin/env python3
"""Validate structural provenance for Imperius Cucked. Does NOT independently verify comic content."""
import argparse
import csv
import sys
from pathlib import Path
from urllib.parse import urlparse

REQUIRED_CLAIMS = ["claim_id", "proposition", "status", "rationale", "primary_evidence_ids", "contrary_evidence_ids"]
REQUIRED_EVIDENCE = ["evidence_id", "claim_id", "series", "issue", "publication_date", "continuity", "source_type", "url", "access_level", "page_panel", "observation", "direction", "verification_status", "notes"]
REQUIRED_CONTRADICTIONS = ["contradiction_id", "claim_id", "evidence_ids", "why_it_matters", "resolution"]
VERDICTS = {"UNTESTED", "UNRESOLVED", "NOT_ESTABLISHED", "SUPPORTED_INFERENCE", "INTERPRETIVE", "CANONICALLY_CONFIRMED", "CANONICALLY_CONTRADICTED", "DISPUTED"}
SOURCES = {"PRIMARY_COMIC", "PRIMARY_CREATOR", "PUBLISHER_METADATA", "SECONDARY", "UNVERIFIED"}
ACCESS = {"FULL_ISSUE_READ", "LEGAL_PAGE_PREVIEW", "CREATOR_ORIGINAL", "METADATA_ONLY", "SECONDARY_SUMMARY", "UNAVAILABLE"}
DIRECTIONS = {"SUPPORTS", "CONTRADICTS", "CONTEXT", "AMBIGUOUS"}
PROOF = {"VERIFIED_PANEL", "VERIFIED_CREATOR", "VERIFIED_METADATA", "SECONDARY_UNVERIFIED", "UNVERIFIED"}
DECISIVE = {"CANONICALLY_CONFIRMED", "CANONICALLY_CONTRADICTED"}


def read_table(root, relative, expected, errors):
    path = root / relative
    if not path.is_file():
        errors.append(f"Missing required file: {relative}")
        return []
    with path.open(newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        cols = reader.fieldnames or []
        missing = [x for x in expected if x not in cols]
        if missing:
            errors.append(f"{relative}: missing columns {missing}")
            return []
        rows = list(reader)
    return rows


def ids(raw):
    return [x.strip() for x in (raw or "").replace(";", ",").split(",") if x.strip()]


def valid_https(url):
    parts = urlparse(url)
    return parts.scheme == "https" and bool(parts.netloc)


def validate(root):
    root = Path(root)
    errors = []
    claims = read_table(root, "data/claims.csv", REQUIRED_CLAIMS, errors)
    evidence = read_table(root, "data/evidence.csv", REQUIRED_EVIDENCE, errors)
    contrad = read_table(root, "data/contradictions.csv", REQUIRED_CONTRADICTIONS, errors)
    claim_ids = set()
    evidence_ids = set()
    ev_by_id = {}
    for number, row in enumerate(evidence, 2):
        ident = (row.get('evidence_id') or '').strip()
        if not ident or ident in evidence_ids:
            errors.append(f"evidence.csv:{number}: empty or duplicate evidence_id: {ident!r}")
        evidence_ids.add(ident)
        ev_by_id[ident] = row
        typ = row.get('source_type', '')
        access = row.get('access_level', '')
        status = row.get('verification_status', '')
        if typ not in SOURCES:
            errors.append(f"evidence.csv:{number}: invalid source_type {typ!r}")
        if access not in ACCESS:
            errors.append(f"evidence.csv:{number}: invalid access_level {access!r}")
        if status not in PROOF:
            errors.append(f"evidence.csv:{number}: invalid verification_status {status!r}")
        if row.get('direction') not in DIRECTIONS:
            errors.append(f"evidence.csv:{number}: invalid direction {row.get('direction')!r}")
        if not valid_https(row.get('url') or ''):
            errors.append(f"evidence.csv:{number}: missing or non-https source URL")
        if status == 'VERIFIED_PANEL':
            if typ != 'PRIMARY_COMIC' or access not in {'FULL_ISSUE_READ', 'LEGAL_PAGE_PREVIEW'}:
                errors.append(f"evidence.csv:{number}: publisher metadata or secondary content cannot certify panel text; read the actual primary comic")
            if not row.get('page_panel') or not row.get('observation'):
                errors.append(f"evidence.csv:{number}: panel verification requires page/panel and observation")
        if status == 'VERIFIED_CREATOR' and (typ != 'PRIMARY_CREATOR' or access != 'CREATOR_ORIGINAL'):
            errors.append(f"evidence.csv:{number}: creator verification requires original statement")
        if status == 'VERIFIED_METADATA' and typ != 'PUBLISHER_METADATA':
            errors.append(f"evidence.csv:{number}: metadata verification must use PUBLISHER_METADATA")
        if not row.get('claim_id', '').strip():
            errors.append(f"evidence.csv:{number}: missing claim_id")
        if not row.get('series', '').strip() or not row.get('issue', '').strip():
            errors.append(f"evidence.csv:{number}: missing issue ID; for creator statements use n/a and identify the interview in notes")
    for number, row in enumerate(claims, 2):
        ident = (row.get('claim_id') or '').strip()
        if not ident or ident in claim_ids:
            errors.append(f"claims.csv:{number}: empty or duplicate claim_id {ident!r}")
        claim_ids.add(ident)
        status = (row.get('status') or '').strip()
        if status not in VERDICTS:
            errors.append(f"claims.csv:{number}: unsupported status {status!r}")
        direct_ids = ids(row.get('primary_evidence_ids'))
        all_refs = direct_ids + ids(row.get('contrary_evidence_ids'))
        for ref in all_refs:
            if ref not in ev_by_id:
                errors.append(f"claims.csv:{number}: unknown evidence ID {ref}")
        if status in DECISIVE:
            verified_direct = [ev_by_id.get(ref) for ref in direct_ids if ref in ev_by_id]
            verified_direct = [r for r in verified_direct if r.get('source_type') == 'PRIMARY_COMIC' and r.get('verification_status') == 'VERIFIED_PANEL']
            if not verified_direct:
                errors.append(f"claims.csv:{number}: {status} requires at least one verified primary comic panel in primary_evidence_ids")
            if not (row.get('rationale') or '').strip():
                errors.append(f"claims.csv:{number}: decisive verdict requires rationale")
    for number, row in enumerate(evidence, 2):
        if row.get('claim_id') not in claim_ids:
            errors.append(f"evidence.csv:{number}: unknown claim ID {row.get('claim_id')!r}")
    for number, row in enumerate(contrad, 2):
        if row.get('claim_id') not in claim_ids:
            errors.append(f"contradictions.csv:{number}: unknown claim ID {row.get('claim_id')!r}")
        for ref in ids(row.get('evidence_ids')):
            if ref not in evidence_ids:
                errors.append(f"contradictions.csv:{number}: unknown evidence ID {ref}")
    return errors


def main():
    parser = argparse.ArgumentParser(description='Structural evidence audit; not factual/comic verification')
    parser.add_argument('--root', default=str(Path(__file__).resolve().parent.parent))
    args = parser.parse_args()
    errors = validate(Path(args.root))
    if errors:
        print('RECEIPT AUDIT: FAILED')
        for e in errors:
            print(' - ' + e)
        return 1
    print('RECEIPT AUDIT: PASSED (structural only; comic content and reasoning still require manual review)')
    return 0

if __name__ == '__main__':
    sys.exit(main())
