#!/usr/bin/env python3
"""Structural evidence quality gate for IMPERIUS CUCKED.

This validates provenance and internal consistency, NOT the authenticity of a panel.
Use it before drafting and before handing off a final report.
"""
import argparse
import json
import re
from datetime import date
from pathlib import Path
from urllib.parse import urlparse

STATUSES = {'VERIFIED','INFERRED','INTERPRETIVE','DISPUTED','UNRESOLVED','FALSIFIED'}
TRACKS = {'namor','franklin','continuity','methodology'}
KINDS = {'bibliographic','plot','theory'}
TYPES = {'primary_comic_panel','primary_creator_interview','official_issue_metadata','secondary','missing'}
ACCESS = {'full_page_read','official_preview','reliable_transcript','metadata_only','unavailable'}
CONFIDENCE = {'high','moderate','low','not_assessed'}
REQUIRED = {
    'evidence_id','claim_id','claim','track','claim_kind','status','continuity',
    'source_type','title','issue','publication_date','source_url','location',
    'access','observation','interpretation','contradiction_ids','confidence',
    'falsification_target','logical_exclusion'
}
RE_ID = re.compile(r'^E-\d{3,}$')
RE_REF = re.compile(r'\[@(E-\d{3,})\]')

def _nonempty(value):
    return isinstance(value,str) and bool(value.strip())

def validate_record(rec, line):
    p = f'line {line}'
    if not isinstance(rec,dict):
        return [f'{p}: expected JSON object']
    issues=[]
    missing=REQUIRED-set(rec)
    if missing: issues.append(f'{p}: missing fields: {", ".join(sorted(missing))}')
    if not RE_ID.fullmatch(str(rec.get('evidence_id',''))):
        issues.append(f'{p}: evidence_id must look like E-001')
    for key,allowed in [('track',TRACKS),('claim_kind',KINDS),('status',STATUSES),('source_type',TYPES),('access',ACCESS),('confidence',CONFIDENCE)]:
        if rec.get(key) not in allowed:
            issues.append(f'{p}: {key} must be one of {sorted(allowed)}')
    for key in ('claim_id','claim','continuity','title','observation'):
        if not _nonempty(rec.get(key)):
            issues.append(f'{p}: {key} must be nonempty')
    if not isinstance(rec.get('contradiction_ids'),list):
        issues.append(f'{p}: contradiction_ids must be an array')
    elif not all(isinstance(s,str) and RE_ID.fullmatch(s) for s in rec['contradiction_ids']):
        issues.append(f'{p}: contradiction_ids must contain evidence IDs')
    url=rec.get('source_url','')
    if _nonempty(url):
        parsed=urlparse(url)
        if parsed.scheme not in ('http','https') or not parsed.netloc:
            issues.append(f'{p}: source_url is not a valid http(s) URL')
    elif rec.get('status') not in ('UNRESOLVED','INTERPRETIVE'):
        issues.append(f'{p}: source_url required for status {rec.get("status")}')
    dt=rec.get('publication_date','')
    if dt and isinstance(dt,str):
        try: date.fromisoformat(dt)
        except ValueError: issues.append(f'{p}: publication_date must be YYYY-MM-DD when known')
    elif dt:
        issues.append(f'{p}: publication_date must be string')
    status=rec.get('status')
    direct=rec.get('source_type') in ('primary_comic_panel','primary_creator_interview')
    primary_access=rec.get('access') in ('full_page_read','official_preview','reliable_transcript')
    if status in ('VERIFIED','FALSIFIED'):
        bibliographic_metadata=(rec.get('claim_kind')=='bibliographic' and rec.get('source_type')=='official_issue_metadata' and rec.get('access')=='metadata_only')
        if not ((direct and primary_access) or (status=='VERIFIED' and bibliographic_metadata)):
            issues.append(f'{p}: {status} requires directly inspected primary evidence (metadata may verify only bibliographic facts)')
        if not _nonempty(rec.get('location')) and not bibliographic_metadata:
            issues.append(f'{p}: {status} requires source location (page/panel, direct interview time, etc.)')
        if not _nonempty(rec.get('observation')):
            issues.append(f'{p}: {status} requires exact observation')
    if status == 'FALSIFIED':
        if not _nonempty(rec.get('falsification_target')):
            issues.append(f'{p}: FALSIFIED requires falsification_target')
        if not _nonempty(rec.get('logical_exclusion')):
            issues.append(f'{p}: FALSIFIED requires logical_exclusion explaining why evidence rules out the unchanged proposition')
    return issues

def validate_file(path):
    issues=[];seen=set();count=0
    if not path.exists(): return [f'{path}: file not found'],0
    for i,line in enumerate(path.read_text(encoding='utf-8').splitlines(),1):
        if not line.strip(): continue
        try: rec=json.loads(line)
        except json.JSONDecodeError as e:
            issues.append(f'line {i}: invalid JSON: {e}');continue
        count+=1
        issues.extend(validate_record(rec,i))
        record_id=rec.get('evidence_id') if isinstance(rec,dict) else None
        if record_id in seen: issues.append(f'line {i}: duplicate evidence_id {record_id}')
        if record_id: seen.add(record_id)
    if count == 0: issues.append('Evidence ledger has no records: cannot claim the research is validated')
    return issues,count

def validate_report_refs(path, ids):
    if not path.exists(): return [f'{path}: report not found']
    references=set(RE_REF.findall(path.read_text(encoding='utf-8')))
    return [f'{path}: unknown evidence reference {x}' for x in sorted(references-ids)]

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('ledger',nargs='?',default='evidence/evidence.jsonl')
    parser.add_argument('--report',help='Optional Markdown report using [@E-001] evidence references')
    args=parser.parse_args()
    ledger=Path(args.ledger)
    problems,n=validate_file(ledger)
    if args.report:
        valid=set()
        if ledger.exists():
            for line in ledger.read_text(encoding='utf-8').splitlines():
                try:
                    item=json.loads(line)
                    if isinstance(item,dict): valid.add(item.get('evidence_id'))
                except json.JSONDecodeError: pass
        problems.extend(validate_report_refs(Path(args.report),valid))
    print(f'Checked {n} evidence records: {len(problems)} structural problems')
    for issue in problems: print('FAIL:',issue)
    if not problems:
        print('PASS: structural evidence checks only; provenance/content still require human inspection')
    return 1 if problems else 0

if __name__=='__main__':
    raise SystemExit(main())
